"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { ChevronDown, CircleHelp } from "./icons";

// Select: generated by UIX from the design system. Same variants and sizes as the Figma component.

const selectVariants = cva(
  "flex w-full items-center transition-colors [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-icon-secondary rounded-md",
  {
    variants: {
      appearance: {
        outline: "border border-line-default bg-surface hover:border-line-strong focus-within:ring-3 focus-within:ring-line-focus focus-within:border-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-disabled",
        filled: "border border-transparent bg-subtle hover:bg-muted focus-within:ring-3 focus-within:ring-line-focus focus-within:border-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-disabled",
        underline: "rounded-none border-0 border-b bg-transparent px-0 border-line-default hover:border-line-strong focus-within:border-b-2 focus-within:border-line-focus has-[:disabled]:cursor-not-allowed",
      },
      size: {
        sm: "h-8 px-3 gap-2",
        md: "h-10 px-3 gap-2",
        lg: "h-12 px-4 gap-2",
      },
    },
    compoundVariants: [
      { appearance: "underline", class: "rounded-none px-0" },
    ],
    defaultVariants: {
      appearance: "outline",
      size: "md",
    },
  },
);

export interface SelectProps
  extends Omit<React.SelectHTMLAttributes<HTMLSelectElement>, "size" | "prefix">,
    VariantProps<typeof selectVariants> {
  label?: React.ReactNode;
  /** Right-aligned note next to the label, for example "Optional". */
  secondaryLabel?: React.ReactNode;
  /** Message under the field. */
  feedback?: React.ReactNode;
  /** Same as feedback. */
  helper?: React.ReactNode;
  /** Error message; also marks the field invalid and replaces the feedback. */
  error?: string;
  /** First, disabled option shown until a value is picked. */
  placeholder?: string;
  /** Avatar at the start (for example <Avatar size="xs" initials="AB" />). */
  leadingAvatar?: React.ReactNode;
  /** Icon at the start. */
  leadingIcon?: React.ReactNode;
  /** Selector or text at the start, for example "Email ▾". */
  leadingContent?: React.ReactNode;
  /** Hairline after the leading parts. */
  leadingDivider?: boolean;
  /** Fixed text before the value, for example "https://". */
  prefix?: React.ReactNode;
  /** Tag chips before the value. */
  tags?: React.ReactNode[];
  /** Fixed text after the value, for example ".com". */
  suffix?: React.ReactNode;
  /** Hairline before the trailing parts. */
  trailingDivider?: boolean;
  /** Action at the end, for example a "Copy" button. */
  trailingContent?: React.ReactNode;
  /** Help icon; a string becomes its accessible name and tooltip. */
  helpIcon?: boolean | string;
  /** Icon at the end. */
  trailingIcon?: React.ReactNode;
}

const Select = React.forwardRef<HTMLSelectElement, SelectProps>(
  ({ className, appearance, size, label, secondaryLabel, feedback, helper, error, required, id, disabled, placeholder, leadingAvatar, leadingIcon, leadingContent, leadingDivider, prefix, tags, suffix, trailingDivider, trailingContent, helpIcon, trailingIcon, children, ...props }, ref) => {
    const autoId = React.useId();
    const fieldId = id ?? autoId;
    const hintId = fieldId + "-hint";
    const message = error || feedback || helper;
    const hint = message ? { "aria-describedby": hintId } : {};
    const initial = placeholder && props.value == null && props.defaultValue == null ? { defaultValue: "" } : {};
    return (
      <div data-slot="select" data-kind="field" className={cn("skin-quiet flex w-full flex-col gap-1-5", className)}>
        {label ? (
          <div className="flex items-baseline justify-between gap-2">
            <label htmlFor={fieldId} className={cn("text-label-medium text-fg-primary", disabled && "text-fg-disabled")}>
              {label}
              {required ? <span aria-hidden className="ml-0.5 text-fg-danger">*</span> : null}
            </label>
            {secondaryLabel ? <span className="text-body-small text-fg-tertiary">{secondaryLabel}</span> : null}
          </div>
        ) : null}
        <div data-kind="field" className={cn(selectVariants({ appearance, size }), error && "border-line-danger hover:border-line-danger focus-within:border-line-danger focus-within:ring-line-danger")}>
          {leadingAvatar}
          {leadingIcon}
          {leadingContent ? <span className="shrink-0 text-body-medium text-fg-secondary">{leadingContent}</span> : null}
          {leadingDivider ? <span aria-hidden className="h-5 w-px shrink-0 bg-line-default" /> : null}
          {prefix ? <span className="shrink-0 text-body-medium text-fg-secondary">{prefix}</span> : null}
          {tags?.map((tag, index) => (
            <span key={index} className="inline-flex shrink-0 items-center rounded-full bg-subtle text-fg-primary text-label-small px-2 py-0-5">
              {tag}
            </span>
          ))}
          <span className="relative flex min-w-0 flex-1 items-center">
            <select ref={ref} id={fieldId} disabled={disabled} required={required} aria-invalid={!!error} {...hint} {...initial} className="block w-full min-w-0 appearance-none bg-transparent pr-6 outline-none text-body-medium text-fg-primary disabled:text-fg-disabled disabled:cursor-not-allowed" {...props}>
              {placeholder ? (
                <option value="" disabled>
                  {placeholder}
                </option>
              ) : null}
              {children}
            </select>
            <span className="pointer-events-none absolute right-0 inline-flex">{trailingIcon ?? <ChevronDown aria-hidden />}</span>
          </span>
          {suffix ? <span className="shrink-0 text-body-medium text-fg-secondary">{suffix}</span> : null}
          {trailingDivider ? <span aria-hidden className="h-5 w-px shrink-0 bg-line-default" /> : null}
          {trailingContent ? <span className="shrink-0 cursor-pointer text-label-medium text-fg-brand">{trailingContent}</span> : null}
          {helpIcon ? (
            <span role="img" aria-label={typeof helpIcon === "string" ? helpIcon : "Help"} title={typeof helpIcon === "string" ? helpIcon : void 0} className="inline-flex shrink-0 text-icon-secondary">
              <CircleHelp aria-hidden />
            </span>
          ) : null}
        </div>
        {message ? (
          <p id={hintId} className={cn("text-body-small text-fg-secondary", error && "text-fg-danger")}>
            {message}
          </p>
        ) : null}
      </div>
    );
  },
);
Select.displayName = "Select";

export { Select, selectVariants };
